CREATE TYPE "public"."post_status" AS ENUM('Terbit', 'Draft');--> statement-breakpoint
CREATE TABLE "posts" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
  "title" varchar(180) NOT NULL,
  "slug" varchar(180) NOT NULL,
  "category" varchar(60) NOT NULL,
  "image" varchar(500) NOT NULL,
  "excerpt" varchar(220) NOT NULL,
  "content" text[] NOT NULL,
  "author" varchar(120) NOT NULL,
  "status" "post_status" DEFAULT 'Draft' NOT NULL,
  "published_at" timestamp with time zone NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);--> statement-breakpoint
CREATE UNIQUE INDEX "posts_slug_uq" ON "posts" USING btree ("slug");--> statement-breakpoint
CREATE INDEX "posts_status_published_at_idx" ON "posts" USING btree ("status","published_at");--> statement-breakpoint
CREATE INDEX "posts_updated_at_idx" ON "posts" USING btree ("updated_at");--> statement-breakpoint
INSERT INTO "posts" ("title", "slug", "category", "image", "excerpt", "content", "author", "status", "published_at", "created_at", "updated_at") VALUES
('Festival Inovasi Sains 2026: Ide Kecil, Dampak Besar', 'festival-inovasi-sains-2026', 'Akademik', '/images/science.jpg', 'Lebih dari 40 proyek siswa dipamerkan, mulai dari penyaring air sederhana hingga sistem kebun pintar berbasis sensor.', ARRAY['Aula SMP Nurul Huda berubah menjadi ruang eksplorasi pada Festival Inovasi Sains 2026. Siswa kelas VII hingga IX mempresentasikan gagasan yang lahir dari masalah sederhana di sekitar mereka.', 'Setiap tim mendapat pendampingan guru dan mentor alumni selama enam minggu. Mereka belajar menyusun hipotesis, menguji prototipe, mencatat kegagalan, lalu memperbaiki solusi berdasarkan data.', 'Proyek kebun pintar karya tim kelas VIII terpilih sebagai karya favorit pengunjung. Sistem tersebut mengatur penyiraman berdasarkan kelembapan tanah dan berhasil mengurangi pemakaian air dalam simulasi sekolah.', 'Bagi Nurul Huda, festival ini bukan sekadar kompetisi. Ini adalah ruang aman bagi siswa untuk bertanya, mencoba, gagal, dan kembali dengan rasa ingin tahu yang lebih besar.'], 'Nadia Prameswari', 'Terbit', '2026-09-12T08:00:00.000Z', '2026-09-12T08:00:00.000Z', '2026-09-12T08:00:00.000Z'),
('Belajar Tanpa Batas melalui Kolaborasi Pelajar Asia', 'kolaborasi-pelajar-asia', 'Kegiatan', '/images/students.jpg', 'Program pertukaran virtual mempertemukan siswa Nurul Huda dengan pelajar dari tiga negara untuk membahas kota berkelanjutan.', ARRAY['Selama empat pekan, siswa Nurul Huda bekerja dalam kelompok lintas negara untuk merancang konsep kota yang lebih ramah manusia dan lingkungan.', 'Diskusi berlangsung dalam bahasa Inggris, tetapi tujuan utamanya lebih luas: mendengar sudut pandang yang berbeda, membangun empati, dan belajar menyampaikan gagasan dengan jernih.', 'Program ditutup dengan presentasi virtual yang dihadiri guru dan orang tua. Beberapa gagasan terbaik akan dikembangkan kembali dalam klub riset semester depan.'], 'Tim Komunikasi Nurul Huda', 'Terbit', '2026-09-05T08:00:00.000Z', '2026-09-05T08:00:00.000Z', '2026-09-05T08:00:00.000Z'),
('Ruang Baca Baru, Ruang Tumbuh untuk Semua', 'ruang-baca-baru', 'Fasilitas', '/images/library.jpg', 'Perpustakaan Nurul Huda hadir dengan koleksi baru, area diskusi, dan sudut tenang yang dirancang bersama para siswa.', ARRAY['Perpustakaan bukan lagi sekadar tempat meminjam buku. Di ruang baru Nurul Huda, siswa dapat membaca dengan tenang, berdiskusi dalam kelompok kecil, atau mengembangkan proyek kreatif.', 'Tim OSIS ikut terlibat sejak tahap perencanaan. Masukan mereka melahirkan sudut rekomendasi siswa, papan pertukaran buku, dan jadwal diskusi mingguan bersama guru.', 'Koleksi digital juga dapat diakses dari rumah sehingga kebiasaan membaca tidak berhenti setelah bel pulang berbunyi.'], 'Tim Komunikasi Nurul Huda', 'Terbit', '2026-08-28T08:00:00.000Z', '2026-08-28T08:00:00.000Z', '2026-08-28T08:00:00.000Z'),
('Program Beasiswa Nurul Huda 2027 Resmi Dibuka', 'beasiswa-nurul-huda-2027', 'Pengumuman', '/images/campus.jpg', 'Kesempatan bagi calon siswa berprestasi untuk bertumbuh bersama Nurul Huda melalui dukungan pendidikan hingga 100 persen.', ARRAY['SMP Nurul Huda membuka Program Beasiswa Nurul Huda 2027 untuk calon siswa dengan prestasi akademik maupun nonakademik yang kuat.', 'Seleksi dilakukan melalui verifikasi dokumen, tes potensi akademik, serta wawancara calon siswa dan orang tua. Sekolah menilai bukan hanya hasil, tetapi juga semangat belajar dan kontribusi sosial.', 'Pendaftaran beasiswa dilakukan bersamaan dengan PPDB reguler. Informasi persyaratan lengkap tersedia pada halaman pendaftaran.'], 'Tim Komunikasi Nurul Huda', 'Terbit', '2026-08-20T08:00:00.000Z', '2026-08-20T08:00:00.000Z', '2026-08-20T08:00:00.000Z');
